import { Injectable, inject } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import {
    AsyncHandler,
    CalendarEvent,
    OrganisationService,
    SettingsService,
    Space,
    flatten,
    getTimezoneDifferenceInHours,
    i18n,
    notifyError,
    notifySuccess,
    timePeriodsIntersect,
} from '@placeos/common';
import {
    declineEvent,
    queryEvents,
    requestSpacesForZone,
} from '@placeos/events';
import { getModule } from '@placeos/ts-client';
import {
    addMinutes,
    endOfDay,
    endOfMonth,
    endOfWeek,
    format,
    getUnixTime,
    startOfDay,
    startOfMonth,
    startOfWeek,
} from 'date-fns';
import { BehaviorSubject, Observable, combineLatest, forkJoin, of } from 'rxjs';
import {
    catchError,
    debounceTime,
    distinctUntilChanged,
    distinctUntilKeyChanged,
    filter,
    first,
    map,
    shareReplay,
    startWith,
    switchMap,
    tap,
} from 'rxjs/operators';

import { openConfirmModal } from '@placeos/components';
import { EventApprovalStateService } from '../events/event-approval-state.service';
import { EventBookModalComponent } from './event-book-modal.component';

export interface BookingFilters {
    /** List of zone ids to get bookings for */
    zone_ids?: string[];
    space_emails?: string[];
    /** @deprecated No longer used for filtering */
    hide_type?: string[];
}

export interface BookingUIOptions {
    /** Whether to show setup and breakdown times for events */
    show_overflow?: boolean;
    /** Whether to show cleaning status of the events */
    show_cleaning?: boolean;
    /** Whether weekends should be shown on week view */
    show_weekends?: boolean;
}

type DayOfWeek = 0 | 1 | 2 | 3 | 4 | 5 | 6;

function periodFor(period, date, tz_offset = 0, week_start: DayOfWeek = 0) {
    const start_result =
        period === 'month'
            ? startOfMonth(date)
            : period === 'week'
              ? startOfWeek(date)
              : startOfDay(date);
    const end_result =
        period === 'month'
            ? endOfMonth(date)
            : period === 'week'
              ? endOfWeek(date, { weekStartsOn: week_start })
              : endOfDay(date);
    const start = addMinutes(start_result, tz_offset * 60);
    const end = addMinutes(end_result, tz_offset * 60);
    return { start, end };
}

@Injectable({
    providedIn: 'root',
})
export class EventsStateService extends AsyncHandler {
    private _org = inject(OrganisationService);
    private _dialog = inject(MatDialog);
    private _settings = inject(SettingsService);
    private _approval_events = inject(EventApprovalStateService);

    /** Emitter for poll events */
    private _poll = new BehaviorSubject<number>(0);
    /** Period to list bookings for */
    private _period = new BehaviorSubject<'month' | 'week' | 'day'>('day');
    /** Event to display */
    private _event = new BehaviorSubject<CalendarEvent>(null);
    /** Event to display */
    private _removed_events = new BehaviorSubject<CalendarEvent[]>([]);
    /** Event to display */
    private _added_events = new BehaviorSubject<CalendarEvent[]>([]);
    /** Filter details for bookings */
    private _filters = new BehaviorSubject<BookingFilters>({});
    /** Filter details for bookings */
    private _options = new BehaviorSubject<BookingUIOptions>({});
    /** Currently active date */
    private _date = new BehaviorSubject<number>(new Date().valueOf());
    /** Currently displayed zone */
    private _zones = new BehaviorSubject<string[]>([]);
    /** Whether booking data is being loaded */
    private _loading = new BehaviorSubject<boolean>(false);
    /** Approval status filter */
    private _approval_filter = new BehaviorSubject<
        'all' | 'incoming' | 'approved' | 'declined'
    >('all');

    /** Observable for active date */
    public readonly date = this._date.asObservable();
    /** Observable for active zone */
    public readonly zones = this._zones.asObservable();
    /** Observable for UI display options */
    public readonly options = this._options.asObservable();
    /** Observable for loading state of bookings */
    public readonly loading = this._loading.asObservable();
    /** Observable for viewed event */
    public readonly event = this._event.asObservable();
    /** Period of time to show events for */
    public readonly period = this._period.asObservable();
    /** Observable for approval filter */
    public readonly approval_filter = this._approval_filter.asObservable();

    public readonly spaces: Observable<Space[]> = combineLatest([
        this._zones,
        this._org.active_region.pipe(
            startWith(null),
            distinctUntilChanged((a, b) => a?.id === b?.id),
        ),
        this._org.active_building.pipe(
            startWith(null),
            distinctUntilChanged((a, b) => a?.id === b?.id),
        ),
    ]).pipe(
        debounceTime(300),
        tap(() => this.unsubWith('bind:')),
        switchMap(([zone_ids]) => {
            this._loading.next(true);
            if (!zone_ids?.length || zone_ids[0] === this._org.region?.id) {
                zone_ids = (this._settings.get('app.use_region')
                    ? this._org
                          .buildingsForRegion(this._org.region)
                          .map((_) => _.id)
                    : null) || [this._org.building?.id];
            }
            const valid_zones = (zone_ids || []).filter(Boolean);
            if (!valid_zones.length) return of([]);
            return forkJoin(
                valid_zones.map((id) => requestSpacesForZone(id)),
            );
        }),
        map((l) => {
            const api_spaces = flatten<Space>(l)
                .filter((_) => _.bookable)
                .sort((a, b) =>
                    (a.display_name || a.name || '').localeCompare(
                        b.display_name || b.name || '',
                    ),
                );
            const mock_spaces = this._approval_events.mockSpaces();
            const existing = new Set(api_spaces.map((s) => s.email));
            const new_spaces = mock_spaces.filter(
                (s) => !existing.has(s.email),
            );
            return [...api_spaces, ...new_spaces];
        }),
        tap(() => this._loading.next(false)),
        shareReplay(1),
    );
    /** Observable for list of bookings */
    public readonly event_list: Observable<CalendarEvent[]> = combineLatest([
        this._period,
        this._zones,
        this._date,
        this.spaces,
        this._poll,
    ]).pipe(
        filter(([period]) => !!period),
        debounceTime(300),
        switchMap(([period, zones, date, spaces]) => {
            if (!zones?.length) return of([]);
            if (zones[0] === this._org.region?.id) {
                zones = (this._settings.get('app.use_region')
                    ? this._org
                          .buildingsForRegion(this._org.region)
                          .map((_) => _.id)
                    : null) || [this._org.building?.id];
            }
            this._loading.next(true);
            const { start, end } = periodFor(
                period,
                date,
                this.tz_offset,
                this._week_start,
            );
            this._removed_events.next([]);
            this._added_events.next([]);

            // Split spaces into driver-bound and API-fetched
            const spaces_with_driver = spaces.filter((s) => s.room_booking_url);
            const spaces_without_driver = spaces.filter(
                (s) => !s.room_booking_url,
            );

            const observables: Observable<CalendarEvent[]>[] = [];

            // Get events from API for spaces without room_booking_url
            if (spaces_without_driver.length > 0) {
                observables.push(
                    queryEvents({
                        strict: 'limit',
                        zone_ids: zones.join(','),
                        period_start: getUnixTime(start),
                        period_end: getUnixTime(end),
                    }).pipe(
                        map((events) =>
                            events.filter((event) =>
                                event.resources.some((resource) =>
                                    spaces_without_driver.some(
                                        (space) =>
                                            space.id === resource.id ||
                                            space.email === resource.email,
                                    ),
                                ),
                            ),
                        ),
                        catchError(() => of([])),
                    ),
                );
            }

            // Get events from driver for spaces with room_booking_url
            for (const space of spaces_with_driver) {
                const driver_events$ = new Observable<CalendarEvent[]>(
                    (subscriber) => {
                        const mod = getModule(space.id, 'Bookings');
                        const binding = mod.variable('bookings');
                        const unsub = binding.bindThenSubscribe((value) => {
                            const events = (value || []).map(
                                (bkn) => new CalendarEvent(bkn),
                            );
                            subscriber.next(events);
                        });
                        this.subscription(`bind:${space.id}`, unsub);
                        return () => this.unsubWith(`bind:${space.id}`);
                    },
                );
                observables.push(driver_events$.pipe(catchError(() => of([]))));
            }

            // Also fetch events from the group events calendar
            const group_calendar = this._settings.get(
                'app.group_events_calendar',
            );
            if (group_calendar) {
                observables.push(
                    queryEvents({
                        period_start: getUnixTime(start),
                        period_end: getUnixTime(end),
                        calendars: group_calendar,
                    }).pipe(
                        map((list) =>
                            list.filter(
                                (_) => _.extension_data?.shared_event,
                            ),
                        ),
                        catchError(() => of([])),
                    ),
                );
            }

            // Combine all event sources and deduplicate
            if (observables.length === 0) return of([]);
            if (observables.length === 1) return observables[0];

            return combineLatest(observables).pipe(
                map((event_lists) => {
                    const all_events = flatten(event_lists);
                    const seen = new Set<string>();
                    return all_events.filter((e) => {
                        if (seen.has(e.id)) return false;
                        seen.add(e.id);
                        return true;
                    });
                }),
            );
        }),
        tap(() => this._loading.next(false)),
        shareReplay(1),
    );
    /** Obsevable for filtered list of bookings */
    public readonly filtered = combineLatest([
        this.event_list,
        this._removed_events,
        this._added_events,
        this._filters,
        this._date,
        this._period,
        this._zones,
        this._approval_events.grouped_calendar_events$,
    ]).pipe(
        map(
            ([
                events,
                removed,
                added,
                filters,
                date,
                period,
                zones,
                mock_events,
            ]: any) => {
                let event_list = [...events];
                event_list.filter(
                    (_) =>
                        !removed.find(
                            (e) =>
                                _.id === e.id || _.ical_uid === e.ical_uid,
                        ),
                );
                event_list = event_list.concat(added);
                const { start, end } = periodFor(
                    period,
                    date,
                    this.tz_offset,
                    this._week_start,
                );
                const filtered_events = this.filterEvents(
                    event_list,
                    start,
                    end,
                    filters,
                    zones,
                );
                const mock_in_range = (mock_events as CalendarEvent[]).filter(
                    (e) =>
                        timePeriodsIntersect(
                            start.valueOf(),
                            end.valueOf(),
                            e.date,
                            e.date + e.duration * 60 * 1000,
                        ),
                );
                return [...filtered_events, ...mock_in_range];
            },
        ),
        shareReplay(1),
    );

    /** Observable for events filtered by approval status */
    public readonly approval_filtered: Observable<CalendarEvent[]> =
        combineLatest([this.filtered, this._approval_filter]).pipe(
            map(([events, filter_value]) => {
                switch (filter_value) {
                    case 'incoming':
                        return events.filter(
                            (e) =>
                                e.status === 'tentative' || e.status === 'none',
                        );
                    case 'approved':
                        return events.filter((e) => e.status === 'approved');
                    case 'declined':
                        return events.filter((e) => e.status === 'declined');
                    default:
                        return events;
                }
            }),
            shareReplay(1),
        );

    public readonly pending: Observable<CalendarEvent[]> = of(1).pipe(
        switchMap(() => {
            const mod = this._org.module('approvals', 'RoomBookingApproval');
            if (!mod) return of([]);
            const binding =
                mod.binding<Partial<CalendarEvent>[]>('approval_required');
            this.subscription('pending', binding.bind());
            return binding
                .listen()
                .pipe(
                    map((_) =>
                        flatten(Object.values(_ || {}))?.map(
                            (i) => new CalendarEvent(i),
                        ),
                    ),
                );
        }),
        shareReplay(1),
    );

    /** Active filters */
    public get filters() {
        return this._filters.getValue();
    }

    public get time_format() {
        return this._settings.time_format;
    }

    public get tz_offset() {
        const tz = this._settings.get('app.events.use_building_timezone')
            ? this._org.building.timezone
            : '';
        const current_tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
        return !tz ? 0 : getTimezoneDifferenceInHours(current_tz, tz);
    }

    private get _week_start() {
        return this._settings.get('app.week_start');
    }

    public getDate() {
        return this._date.getValue();
    }

    public readonly setFilters = (details: BookingFilters) =>
        this._filters.next(details);
    public readonly setDate = (date: number) => this._date.next(date);
    public readonly setPeriod = (period: 'day' | 'week' | 'month') =>
        this._period.next(period);
    public readonly setZones = (zones: string[]) => this._zones.next(zones);
    public readonly setEvent = (event: CalendarEvent) =>
        this._event.next(event);
    public readonly setApprovalFilter = (
        filter_value: 'all' | 'incoming' | 'approved' | 'declined',
    ) => this._approval_filter.next(filter_value);

    public setUIOptions(options: BookingUIOptions) {
        const old_options = this._options.getValue();
        this._options.next({ ...old_options, ...options });
    }

    public startPolling(
        period: 'day' | 'week' | 'month' = 'day',
        delay: number = 30 * 1000,
    ) {
        this._period.next(period);
        return this.poll(delay);
    }

    public poll(delay: number = 30 * 1000) {
        this._poll.next(Date.now());
        this.interval('polling', () => this._poll.next(Date.now()), delay);
        return () => this.stopPolling();
    }

    public stopPolling() {
        this._poll.next(0);
        this.clearInterval('polling');
    }

    public async newBooking(event?: CalendarEvent) {
        const ref = this._dialog.open(EventBookModalComponent, {
            data: { event },
        });
        const details = await Promise.race([
            ref.componentInstance.event
                .pipe(first((_) => _.reason === 'done'))
                .toPromise(),
            ref.afterClosed().toPromise(),
        ]);
        if (details?.reason !== 'done') return;
        this.replace(details.metadata);
    }

    public async removeBooking(event: CalendarEvent) {
        const time = `${format(event.date, 'dd MMM yyyy ' + this.time_format)}`;
        const resource_name = event.space?.display_name || event.location;
        const details = await openConfirmModal(
            {
                title: i18n('APP.CONCIERGE.BOOKING_REMOVE_TITLE'),
                content: i18n('APP.CONCIERGE.BOOKING_REMOVE_MSG', {
                    name: resource_name,
                    time,
                }),

                icon: { class: 'material-symbols-rounded', content: 'delete' },
            },
            this._dialog,
        );
        if (details.reason !== 'done') return false;
        details.loading(i18n('APP.CONCIERGE.BOOKING_REMOVE_LOADING'));
        await declineEvent(event.id, {
            calendar: event.calendar || event.mailbox || event.host,
            system_id: event.system?.id,
        })
            .toPromise()
            .catch((e) => {
                notifyError(
                    i18n('APP.CONCIERGE.BOOKING_REMOVE_ERROR', { error: e }),
                );
                details.close();
                throw e;
            });
        notifySuccess(i18n('APP.CONCIERGE.BOOKING_REMOVE_SUCCESS'));
        this.remove(event);
        this._dialog.closeAll();
        return true;
    }

    /**
     * Update booking in the bookings list
     * @param booking
     */
    public replace(booking: CalendarEvent) {
        this._removed_events.next([...this._added_events.getValue(), booking]);
        this._added_events.next([...this._added_events.getValue(), booking]);
    }

    /**
     * Remove booking in the bookings list
     * @param booking
     */
    public remove(booking: CalendarEvent) {
        this._removed_events.next([
            ...this._removed_events.getValue(),
            booking,
        ]);
    }

    private filterEvents(
        events: CalendarEvent[],
        start: Date,
        end: Date,
        filters: BookingFilters,
        zones: string[] = [],
    ) {
        return events.filter((bkn) => {
            const intersects = timePeriodsIntersect(
                start.valueOf(),
                end.valueOf(),
                bkn.date,
                bkn.date + bkn.duration * 60 * 1000,
            );
            const has_space =
                !filters.space_emails?.length ||
                !!bkn.resources.find((space) =>
                    filters.space_emails.includes(space.email),
                );
            const in_zones =
                !filters.zone_ids?.length ||
                !!bkn.resources.find((space) =>
                    space.zones.find((zone) => filters.zone_ids.includes(zone)),
                );
            return intersects && has_space && in_zones;
        });
    }
}
